* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * **			                  **      A P P L E   I I g s   I N S T A L L E R   P R O G R A M   V  2 . 0     **                                                                             **                              by "Jay" Schaffer                              **                               and  Ron Lichty                               **			                  ** This program permits adding, replacing, and/or deleting files on a volume   ** based on instructions contained in a 'script' file.	                  **			                  **  Copyright Apple Computer, Inc. 1987-1991              All Rights Reserved  **			                  ** * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * ** Note:  Release Notes have been moved to Release Notes.Installer.	Eject	String AsIs	Blanks Off	Print Push	Print Off	include 'Installer.Equates'	include 'Installer.Records'	Include 'Version.Macros'	Print Pop	Seg 'Main'	SegAttr Static* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *Installer	Proc** Description:	Main entry point for the installer program.  Also contains*	copyright notice and version information.** Inputs:	none** Outputs:	none** External Refs:	Import Allocate	Import CantPrintMsg	Import ContinueStr	Import CursorArrowOn	Import CursorWatchOn	Import CustomProgram	Import D_DeviceNum	Import DeathMsg	Import DeReference	Import DialogFlag	Import DispDisk2Update2	Import EndCantPrintMsg	Import EraseDiskState	Import GotSCSICard	Import GStrAsC1Inp	Import HaltStr	Import Help_GotoEasy  ; delete if no Easy Update (no RDiskNames resource)	Import Help_LeftArrow	Import InitPrefix	Import InitVolume	Import InstallRemoveMode	Import loadDiskNames	Import messageHandle	Import MyID	Import MyToolID	Import NextDevice1	Import Preferences	Import PrefixPointer	Import QuitFlag	Import SavePrefix0	Import ScriptListBuilt	Import ScriptListFlag	Import ScriptListSize	Import TargetSetUpComplete	Import StandardNo	Import StandardProgram	Import StandardSetupComplete	Import SysPrefParms	Import TargetIsOpen	Import ToolStartup	Import WindowSetupComplete	Import WindowType** Entry Points:	Export AllDone	Export AlmostAllDone	Export cVersion	Export MoreDone	Export startStopRecRefRet	Export SysDeath	Export wTitleCustom	Export wTitleStd	Export wVersion** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	brl Real_Start;---------------------------------------------------------------	dc.b '(c) Copyright Apple Computer, Inc. 1987-1993'wTitleStd	dc.b wTitleStdEnd-*-1	dc.b ' Apple IIGS Installer - Easy Update ' ; (Leading and trailing spaces)wTitleStdEndwTitleCustom	dc.b wTitleCustomEnd-*-1	dc.b ' Apple IIGS Installer v2.1 - Customized Installation ' ; (Leading and trailing spaces)wTitleCustomEndwVersion	InstallerVersion	; Macro inserts current version herecVersion	dc.b '1.00'	; Script compatibility version numbers	dc.b '1.10'	dc.b '2.00';--------------------------------------------------------------- 	EjectReal_Start	phk	; Save the bank we're running from		;   so we can set the B-reg later.; Initialize variables as needed.	phk	plb	; Set our data bank register first	sec	; Signify "Easy Update" dialog	ror DialogFlag	;   is currently running.	stz TargetSetUpComplete	stz TargetIsOpen	; no target volume yet	stz ScriptListSize	; Initialize the ScriptListSize value	stz ScriptListFlag	;   and ScriptListFlag	stz ScriptListBuilt	stz QuitFlag	stz InstallRemoveMode	stz WindowType	; save current window type: 0 in bit 15 = Installer wdw	ldx #EnableMItem	stx EraseDiskState; Startup tools as needed and initialize the device list.	jsl ToolStartup	; Startup "everything"	pha	; Unload 'StartUp' segment	pha	; 3-words for results	pha	pea ToolStartup>>16	pea |ToolStartup	ldx #UnloadSeg	jsl ToolLocator	pla	; discard UserID	pla	; discard loadFileNum	pla	; discard loadSegNum	plb	; Set our data bank register	jsr InitPrefix	; Initialize the system prefix	jsr InitVolume	; Initialize Volume_Parm table;rdl redundant: set in InitVolume	lda #0001	; Initialize device number;	sta D_DeviceNum	jsr loadDiskNames	; load DiskName resources; if none, set StandardNo (goto Custom); Check StandardNo (no DiskName resource); if clear, Easy Update: put 'Hard Drive Init' menu only if SCSI exists	lda StandardNo	bne @ChkMsgCtr	; bra if Developer Version of Installer (no Easy Update)	lda GotSCSICard	; existence of SCSI card tested in ToolStartup routine	bne @ChkMsgCtr	; got SCSI card: full-featured Easy Update	jsr noSCSI	; if no SCSI card: remove 'Hard Drive Init' menu item ; Check with the message center to see if there is a message for us.  (Pass the; message center an empty handle and it'll resize it to hold the message, if any.)@ChkMsgCtr	lda #0000	; Size of block to create	jsl Allocate	stx MessageHandle	sty MessageHandle+2	bcs @Oops	pea 0002	; action (Get)	pea 0001	; type (File Info)	phy	; messageHandle	phx	ldx #MessageCenter	jsl ToolLocator	bcc ExamineMessage	cmp #mesNotFoundErr	; Specified message not found?	beq NoMessage	; No message.@Oops	brl AllDone	; We got a message.  If it isn't an "OPEN", we need to get further instructions; from the user about how to proceed.ExamineMessage	ldy MessageHandle+2	ldx MessageHandle	phy	; Push handle to dereference	phx	phy	; Push Handle to lock	phx	ldx #HLock	; Lock the handle	jsl ToolLocator	jsl Dereference	; Dereference the handle	pla	sta <ZPTemp	pla	sta <ZPTemp+2	ldy #0006	lda [<ZPTemp],y	; messageData: 0="Open", 1="Print"	bne @0	brl ToCustom	; If OPEN, GOTO Customized dialog@0; The user asked us to print the selected scripts.  We can't do that!  Respond; with a dialog asking what to do...	jsr CursorArrowOn	; Get an arrow cursor.	pha	; Room for result	pea StopAlert1>>16	; alertTemplatePtr	pea |StopAlert1	pea 0000	; filterProcPtr	pea 0000	ldx #StopAlert	jsl ToolLocator	jsr CursorWatchOn	; Get the watch cursor back before		;   checking to see what was hit.	pla	; ID of item hit	cmp #0002	; "HALT" button ?	beq AllDone	bra ToCustom	; "CONTINUE" was hit.	Eject; We had no messages.  Dispose of the handle we passed to the message center; and fall through to Standard Installation routines.NoMessage	lda MessageHandle+2	pha	lda MessageHandle	pha	ldx #DisposeHandle	jsl ToolLocator	stz MessageHandle	stz MessageHandle+2; Check StandardNo (no DiskName resource): if set, go to Custom (3rd party developer feature)	lda StandardNo	bne @NoEasy2	; bra if Developer Version of Installer (no Easy Update); We know we're going to Easy Update	jsr NextDevice1	; find a target volume to which we can Install (not dimmed)	sec	ror TargetSetUpComplete ; done setting up	bra Standard	; Easy Update; no Easy Update!; remove ‘Go to Easy Update’ from Keyboard Shortcuts Help dialog@NoEasy2	stz Help_GotoEasy	; delete (no Easy Update--no RDiskNames resource)	stz Help_GotoEasy+2	stz Help_LeftArrow	stz Help_LeftArrow+2ToCustom	sec	ror TargetSetUpComplete ; going to Custom, for the first time	bra Custom	; now put up the Customized Installation window; No Messages.  DiskName resource exists.  Bring up the Standard Installation dialog.;   Then switch between Standard and Custom as user chooses.Standard	jsl StandardProgram	bit QuitFlag	bmi AllDone; We had an OPEN message in the message center.  Bring up the Customized; Installation dialog with the proper scripts hilited.Custom	jsl CustomProgram	bit QuitFlag	bpl Standard; Shut down everything and make a GS/OS QUIT callAllDone	pea $0001	; startStopDesc - handle	lda startStopRecRefRet+2 ; startStopRecRef	pha	lda startStopRecRefRet	pha	ldx #ShutDownTools	jsl ToolLocator; Restore the system preferences and the caller's original prefix, then quitAlmostAllDone	lda Preferences	sta SysPrefParms+2	jsl GSOS	dc.w Set_Sys_Pref	dc.l SysPrefParms	pei <PrefixHandle+2	; Lock the prefix's buffer	pei <PrefixHandle	ldx #HLock	jsl ToolLocator	pha	; long for GStrAsC1Inp to use for its result	pha	pei <PrefixHandle+2	; Dereference the prefix's handle	pei <PrefixHandle	jsl Dereference	; leave ptr on stack for GStrAsC1Inp to use; Use GStrAsC1Inp to fix the pointer just dereferenced (& still on stack) to point to ;   the Class 1 input string portion of the Class 1 output string (GStr).	jsl GStrAsC1Inp	pla	sta PrefixPointer	pla	sta PrefixPointer+2	jsl GSOS	; Restore the system prefix	dc.w Set_Prefix	dc.l SavePrefix0MoreDone	lda MyID	; Dispose of any memory still allocated	pha	ldx #DisposeAll	jsl ToolLocator	lda MyToolID	pha	ldx #DisposeAll	jsl ToolLocator	lda MyID	; Shut down the last two tools	and #$F0FF	pha	ldx #MMShutDown	jsl ToolLocator	ldx #TLShutDown	jsl ToolLocator	jsl GSOS	; The End!	dc.w Quit	dc.l QuitParams; Use this entry point when we encounter a fatal error that might prevent the; system from even recovering after a QUIT call.SysDeath	pea DeathMsg>>16	pea |DeathMsg	ldx #SysFailMgr	jsl ToolLocator	Eject; Template for the StopAlertStopAlert1@Height	equ 75@Width	equ 340	dc.w 100-@Height/2		; atBoundsRect - top	dc.w 320-@Width/2		;              - left	dc.w 100+@Height/2		;              - bottom	dc.w 320+@Width/2		;              - right	dc.w 0001		; atAlertID	dc.b $80,$80,$80,$80	; atStage1...atStage4	dc.l @Item1		; item1Ptr	dc.l @Item2		; item2Ptr	dc.l @Item3		; item3Ptr	dc.l 00000000		; terminator@item1	dc.w 0001		; itemID	dc.w @Height-17		; itemRect - top	dc.w @Width-110		;          - left	dc.w @Height-5		;          - bottom	dc.w @Width-13		;          - right	dc.w ButtonItem		; itemType	dc.l ContinueStr		; itemDescr (title string)	dc.w 0000		; itemValue	dc.w 0000		; itemFlag	dc.l 00000000		; itemColor@Item2	dc.w 0002		; itemID	dc.w @Height-17		; itemRect - top	dc.w 10		;          - left	dc.w @Height-5		;          - bottom	dc.w 110		;          - right	dc.w ButtonItem		; itemType	dc.l HaltStr		; itemDescr (title string)	dc.w 0000		; itemValue	dc.w 0000		; itemFlag	dc.l 00000000		; itemColor@Item3	dc.w 0003		; itemID	dc.w 26		; itemRect - top	dc.w 10		;          - left	dc.w @Height-20		;          - bottom	dc.w @Width-10		;          - right	dc.w LongStatText2+itemDisable	; itemType	dc.l CantPrintMsg		; itemDescr (title string)	dc.w EndCantPrintMsg-CantPrintMsg	; itemValue	dc.w 0000		; itemFlag	dc.l 00000000		; itemColor	; Parameter table for the GS/OS QUIT call.QuitParams	dc.w 0002	; pCount	dc.l $00000000	; pathname	dc.w $0000 ;<--- •••• NOT restartable in memory •••• <---;;;	dc.w $4000	; Restartable in memory; Handle to startStopRecRefstartStopRecRefRet	dc.l 1	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *noSCSI		; local** Description:	remove ‘Hard Disk Initialization’ menu item & recalculate menu size*** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	pea HardDiskItemID	ldx #DeleteMItem	jsl ToolLocator;         recalculate menu size	pea 0	; let Menu Manager calculate width & height (0,0)	pea 0	pea HelpMenuID	; resize Help menu	ldx #CalcMenuSize	jsl ToolLocator	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *StandardProgram	Proc** Description:	The Standard Update dialog program loop.*	Export ConditionBtns	Export Help2Sub	Export StandardDrawProc	Export TestTopWindow** Description:	Draws the contents of the Easy Update dialog.** Inputs:	none** Outputs:	none** External Refs:	Import BeginStdControl	Import BootVolTest	Import CheckCharacter	Import CheckHilite	Import CheckVolume	Import CurrentVol	Import CursorArrowOn	Import CursorWatchOn	Import D_Cont_DevNum	Import D_Cont_Parms	Import D_DeviceNum	Import D_Info_Parms	Import DialogFlag	Import DiskNamesTest	Import EasyBtnActive	Import EasyBtnDim	Import Eject2Control	Import Eject2CtlHdl	Import EjectSub	Import Error	Import File_Sys_ID	Import FlushEventQueue	Import Help2CtlHdl	Import HelpSub	Import hLineHead	Import hLineHeadEnd	Import hLine1	Import hLine1End	Import hLine2	Import hLine2End	Import hLine3	Import hLine3End	Import hLine4	Import hLine4End	Import inMenu	Import InstallerIcon	Import InstallRemoveMode	Import MyZP	Import NextDevice1	Import OKStr	Import OneSimpleKeyFilter	Import QuitFlag	Import QuitSub	Import ReBootDialog	Import scanDevices	Import SetPrefixCurrVol	Import ScriptListBuilt	Import StandardDialog	Import StandardHdlTable	Import StandardPort	Import StandardSetupComplete	Import StandardUpdateSub	Import SystemIcon	Import Task:TaskRecord	Import VolumeCtlHdl** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	phb	stz StandardSetupComplete	jsr SetPrefixCurrVol ; set prefix to CurrentVol; Call the dynamic segment that does the one-time chores of creating the; window with its controls.  Then, dump the segment.	jsl StandardDialog	; Create the window w/ controls	php	; Preserve cFlag	pha	;   and error code	bcc @0	jsl Error	; Report errors@0	pha	; Unload 'Standard' segment	pha	; 6-bytes for results	pha	pea StandardDialog>>16	pea |StandardDialog	ldx #UnloadSeg	jsl ToolLocator	pla	; discard UserID	pla	; discard loadFileNum	pla	; discard loadSegNum	pla	; Restore error code	plp	;   and cFlag	plb	; Restore our data bank register	bcc @1	brl AllDone@1; Initialize variables, flags, D_Info parameters, and task record.;	jsr DispDisk2Update2	sec	; Signify "Standard Update" dialog	ror DialogFlag	;   is currently running.	lda QuitFlag	; Clear all but ReBoot bit.	and #%0100000000000000	sta QuitFlag	jsl GSOS	; Initialize D_Info_Parms returned values	dc.w D_Info	dc.l D_Info_Parms	jsr CheckCharacter	; Condition "Eject" button, "Erase" menu item; condition ‘Begin Std Update’ button & set var InstallRemoveMode’s hi bit	jsr ConditionBtns		; Define wmTaskMask	lda #tmInfo+\	;  Don't activate inactive window on click in info bar	     tmInactive+\	;  Return "wInactMenu" when user selects inactive menu item	     tmCReDraw+\	;  Redraw controls upon activate event	     tmSpecial+\	;  Handle special menu events	     tmContent+\	;  Activate inactive window upon click in content region	     tmDragW+\	;  DragWindow called	     tmSysClick+\	;  System click called	     tmOpenNDA+\	;  OpenNDA called	     tmMenuSel+\	;  MenuSelect called	     tmFindW+\	;  FindWindow called	     tmUpdate+\	;  Update events handled	     tmMenuKey	;  MenuKey called	sta Task.Mask	lda #tmContentControls+\  ; let TaskMaster handle controls	     tmControlKey	;  give controls key equivalents	sta Task.Mask+2; Finally, if there were no volumes previously on line, try finding one.  The; user surely had to put the Install disk back in to get here from Customized; Installation, if that's where he came from.	lda InstallRemoveMode ; Are there any volumes on line	and #bNoVols	; Isolate "no volumes on line" bit	beq StandardLoop1	jsr NextDevice1	EjectStandardLoop1	jsl FlushEventQueue	jsr CursorArrowOnStandardLoop	lda #$0001	; Always check the QuitFlag	bit QuitFlag	; Exit if SwitchDialogBit is set.	bne AllDone1	bpl @1	; Go on if QuitBit is clear.	bvc AllDone1	; Exit if QuitBit set & ReBootBit clear		; Else tell user he must reboot to quit.  If	jsr ReBootDialog	;  subroutine returns, he cancelled.@1	jsr scanDevices	; (if insert, returns carry set, pointer to 	jsr TestTopWindow	; our window or a DA?; Call TaskMaster to find out what is happening, if anything	pha	; Space for result	pea emDeskAcc+\	; Define EventMask TaskMaster will use	    emActivate+\	;  to call the EventManager	    emUpdate+\	    emKeyDown+\	    emMouseUp+\	    emMouseDown+\	    emAutoKey	pea Task>>16	pea |Task	ldx #TaskMaster	jsl ToolLocator	pla	; Get the TaskCode	beq StandardLoop	; Loop until something happens; Something Happened!	asl a	; Convert code to dispatch index	tax	jsr (TaskTable,x)	;   and dispatch the event	bcc StandardLoop1;       If the error is No Volumes on line, just ignore it and continue.	cmp #$008A	beq StandardLoop1;       If the error is anything else, set the QuitFlag	lda QuitFlag	ora #$8000	sta QuitFlagAllDone1; rdl: error flags not used by caller, so commented out;	clc	; Indicate no errors;	lda #0000AllDone;	php	; Preserve cFlag;	pha	;   and error code	stz DialogFlag	; Standard Update is done	lda StandardPort+2	; Close its window	pha	lda StandardPort	pha	ldx #CloseWindow	jsl ToolLocator;	pla	; Restore error code;	plp	;   and cFlag	rtl	; Return to caller	Eject; TaskMaster Dispatch TableTaskTable	dc.w Ignore	;00=null	\	dc.w Ignore	;01=mouse down	 \	dc.w Ignore	;02=mouse up	  \	dc.w Ignore	;03=key down           \	dc.w Ignore	;04=undefined	    \	dc.w Ignore	;05=auto-key down	     \	dc.w Ignore ;StandardDrawProc ;06=update event\	dc.w Ignore	;07=undefined	       \   Event	dc.w Ignore	;08=activate	        >  Manager	dc.w Ignore	;09=switch	       /   Events	dc.w Ignore	;0A=desk acc	      /	dc.w Ignore	;0B=device driver	     /	dc.w Ignore	;0C=application	    /	dc.w Ignore	;0D=application	   /	dc.w Ignore	;0E=application	  /	dc.w Ignore	;0F=application	 /	dc.w Ignore	;10=in desk	 \	dc.w inMenu	;11=in MenuBar	  \	dc.w Ignore	;12=in system window   \	dc.w Ignore	;13=in content of window\	dc.w Ignore	;14=in drag	     \	dc.w Ignore	;15=in grow	      \	dc.w Ignore	;16=in GoAway	       |	dc.w Ignore	;17=in zoom	       |	dc.w Ignore	;18=in info bar	       \ TaskMaster	dc.w Ignore	;19=in special menu	item   / Events	dc.w Ignore	;1A=in OpenNDA	       |	dc.w Ignore	;1B=in frame	       |	dc.w Ignore	;1C=in inactive menu item /	dc.w Ignore	;1D=wClosedNDA	     /	dc.w Ignore	;1E=wCalledSysEdit	    /	dc.w Ignore	;1F=wTrackZoom	   /	dc.w Ignore	;20=wHitFrame	  /	dc.w inControl	;21=wInControl	 /Ignore	rts	; 'Do nothing' subroutine	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .StandardDrawProc	; (External Entry Point);;	Draws the Standard Update dialog.;	(Parameter to NewWindow2.);; Inputs:	none;; Outputs:	none;; External References:	Import UpdateFlag;; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	lda >StandardSetupComplete	bmi Begin	lda #$8000	sta >StandardSetUpComplete; Save caller's registers and set them for usBegin	phd	; Save caller's direct register	phb	; Save caller's bank register	phk	; Reset bank register...	plb	;  ...to current bank	lda MyZP	; Reset direct register...	tcd	;  ...to Installer's zero page	lda CurrentVol	; convert GS/OS input string	xba	sta CurrentVol	;  ...to pstring; Draw the controls	lda StandardPort+2	pha	lda StandardPort	pha	ldx #DrawControls	jsl ToolLocator	lda CurrentVol	; convert pstring back	xba	sta CurrentVol	;  ...to GS/OS input string	lda UpdateFlag	bne @UpdateInProgress ; bra if script currently being executed	jsr NormalChangeDisk ; condition ‘Change Disk’ button to normal state	bra @DrawProcDone@UpdateInProgress	jsr DimChangeDisk	; condition 'Change Disk' button to dimmed state; Restore caller's registers and return@DrawProcDone	plb	; Restore caller's bank register	pld	; Restore caller's direct register	rtl	; Return to caller	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .TestTopWindow	; (External Entry Point);;	Has the top window changed between ours & a DA?.;	Calls DoSysChange to change menus to match.;; Inputs:	none;; Outputs:	none;; External Refs:	Import WindowType;; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pha	; room for long result	pha	ldx #FrontWindow	jsl ToolLocator	plx	; front WdwPtr	ply	bne @TestContinue	txa	beq TestExit@TestContinue	pha	; room for word result	phy	; front WdwPtr	phx	ldx #GetWKind	jsl ToolLocator	pla	; get window type	cmp WindowType	; compare to previous window type	beq TestExit	sta WindowType	; save current window type	jsr DoSysChange	; window type changed: change menus to matchTestExit	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .DoSysChange	; (local);;	The top window has changed between ours & a DA.;	Change menus to match.;; Inputs:	accum: window type: bit 15 set if top window is a system window.;; Outputs:	none;; Externals:	Import EraseDiskState;; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	tax	bpl AppToFront	; bra if change was to bring app window to front; else system window just became the front window;    disable Help menu;;    enable Edit menu;    enable Close menu item;    disable Erase Disk... menu item	pea disableMenu	pea HelpMenuID	ldx #SetMenuFlag	jsl ToolLocator		pea enableMenu	pea EditMenuID	ldx #SetMenuFlag	jsl ToolLocator	pea CloseWItemID	ldx #EnableMItem	jsl ToolLocator		pea EraseDiskItemID	ldx #DisableMItem	jsl ToolLocator	bra updateMenuBar	; Installer window just became the front window;    enable Help menu;;    disable Edit menu;    disable Close menu item;    restore Erase Disk... menu item to last settingAppToFront	pea enableMenu	pea HelpMenuID	ldx #SetMenuFlag	jsl ToolLocator		pea disableMenu	pea EditMenuID	ldx #SetMenuFlag	jsl ToolLocator		pea CloseWItemID	ldx #DisableMItem	jsl ToolLocator		pea EraseDiskItemID	ldx EraseDiskState	; set in DisableEraseDiskMenu / EnableEraseDiskMenu	jsl ToolLocatorupdateMenuBar	ldx #DrawMenuBar	jsl ToolLocator	rts		Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .inControl	; (Local subroutine);; Description:	inControl event handler...checks to see if we went down;	in an active control and blinks it if we did.   ;; Inputs:	none;; Outputs:	cFlag clear: no errors...A-reg zero.;	cFlag set: error...A-reg contains error code.; . . . . . . . . . . . . . . . . . . . . . . . . . . . 