e segment.	jsl CustomDialog	; Create the dialog & build the script list	php	; Preserve cFlag	pha	;   and error code	pha	; Unload 'Custom' segment	pha	; 6-bytes for results	pha	pea CustomDialog>>16	pea |CustomDialog	ldx #UnloadSeg	jsl ToolLocator	pla	; discard UserID	pla	; discard loadFileNum	pla	; discard loadSegNum	pla	; Restore error code	plp	;   and cFlag	plb	; Set our data bank register	bcc @1	brl CustomExit@1; Initialize flags and TaskRecord	stz <PopUpStringPtr	stz <PopUpStringPtr+2	stz AppFolderListHdl	stz AppFolderListHdl+2	lda QuitFlag	; Clear all but ReBoot bit.	and #%0100000000000000	sta QuitFlag	stz DirSelReq	stz MenuItemID	jsl GSOS	; Initialize D_Info_Parms returned values	dc.w D_Info	dc.l D_Info_Parms; Initialize "InstallRemoveMode".	jsl GSOS	dc.w Volume	dc.l Volume_Parms;       Check that it is "WriteAllowed"	lda D_Info_Parms+8	; Check the characteristics	and #WriteAllowed	beq @NotWriteEnabled;       Activate/deactivate INSTALL and/or REMOVE buttons based on;       whether the volume is write-protected or write-enabled.	jsl CheckVolume	; check CurrentVol	bmi @NotWriteEnabled ; If write-protected, dim control	jsl GSOS	dc.w Get_File_Info	dc.l GetAccessParms	lda GetAccessParms+6	and #%0000000000000010 ; Isolate write bit	bne @WriteEnabled;       The volume is NOT write-enabled!  Deactivate INSTALL and REMOVE;       and notify the user that the disk is not writeable.@NotWriteEnabled	lda InstallRemoveMode	ora #bWriteProtect	; force WriteProtect flag to 1	bra InitTaskMaster;       The volume is write enabled!  Activate INSTALL and REMOVE.@WriteEnabled	lda InstallRemoveMode	and #bWriteProtect--$FFFF ; clear WriteProtect bitInitTaskMaster	sta InstallRemoveMode	lda #tmInfo+\	;  Don't activate inactive window on click in info bar	     tmInactive+\	;  Return "wInactMenu" when user selects inactive menu item	     tmCReDraw+\	;  Redraw controls upon activate event	     tmSpecial+\	;  Handle special menu events	     tmContent+\	;  Activate inactive window upon click in content region	     tmDragW+\	;  DragWindow called	     tmSysClick+\	;  System click called	     tmOpenNDA+\	;  OpenNDA called	     tmMenuSel+\	;  MenuSelect called	     tmFindW+\	;  FindWindow called	     tmUpdate+\	;  Update events handled	     tmMenuKey	;  MenuKey called	sta Task.Mask	lda #tmContentControls  ; let TaskMaster handle controls	sta Task.Mask+2; Always check the characteristics of the initial device.	jsr CheckCharacter	; (••• Draws Eject button, enables Erase menu item •••); Set up all the controls based on the currently selected script(s).	jsr ScriptListSub	; Set up Update Selection window		; (••• Draws Open button ••• ); Always start with Alert Message #1, unless it's set to Alert Message #6	lda AlertMsgNo	cmp #AlertMsg6	beq @noChange	lda #AlertMsg1	sta AlertMsgNo	lda #$FFFF	sta OldMsgNo@noChange	jsr AlertMsg	; (••• Draws Alert message •••)	jsr CursorArrowOn	lda #Active	jsr HelpControl; Finally, if there were no volumes previously on line, try finding one.  The; user surely had to put the Install disk back in to get here.	lda InstallRemoveMode ; Are there any volumes on line	and #bNoVols ; Isolate "no volumes on line" bit	beq MainLoop1	jsr NextDevice1	Eject; - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -; Loop back to here if something happenedMainLoop1	stz <ZPTemp	stz <ZPTemp+2; If we've shut down desk accessories, notify the user what has happened.	bit QuitFlag	bvc MainLoop	lda #AlertMsg5	; 'desk accessories are shut down'	sta AlertMsgNo	jsr AlertMsg; Always check the flag bits of the QuitFlag first.  Here is the order:;   bit  0: (Switch dialogs flag);           If set, clear the bit and go to the Standard Update dialog.;           if clear, check bit 15.;   bit 15: (Quit flag);           If set, check bit 14.;           If clear, continue in the event loop.;   bit 14: (ReBoot flag);           If set, force a re-boot.;           If clear, all done.MainLoop	lda #$0001	; Loop back to here if nothing happened	bit QuitFlag	; Check SwitchDialogFlag (bit 0); If "Switch dialogs flag" is set, user has asked to go to the Standard Update dialog.	bne AllDone	; bra to goto Standard Update	bpl @1	; bra if "Quit flag" is clear: go on	bvc AllDone	; bra if "Re-Boot flag" is not set: quit; "Re-Boot flag" is set: ask user to reboot or cancel	jsr ReBootDialog	; If we return, user cancelled quit.; Check for disk insertions.  If a new volume has been added, look for scripts; add them to the list if they're not duplicate (from re-inserting the same; volume), and redraw the list.@1	jsr scanDevices	; (if insert, returns carry set, pointer to 	jsr TestTopWindow	; our window or a DA?; Call TaskMaster to find out what is happening, if anything	pha	; Space for result	pea emDeskAcc+\	; Define EventMask TaskMaster will use	    emActivate+\	;  to call the EventManager	    emUpdate+\	    emKeyDown+\	    emMouseUp+\	    emMouseDown+\	    emAutoKey	pea Task>>16	pea |Task	ldx #TaskMaster	; (••• Does NOT draw controls 1st time •••)	jsl ToolLocator	pla	; Get the TaskCode	beq MainLoop	; Loop until something happens; Something Happened!	asl a	; Convert code to dispatch index	tax	jsr (TaskTable,x)	;   and dispatch the event	bcc MainLoop1;             If we got a "Volume Not Found" error and the user clicked on "Cancel",;             we need to advance to the next device if that was the one we were;             asking for.	cmp #VolumeNotFound	bne MainLoop1	jsr CursorWatchOn	jsr NextDevice	; Advance conditionally	bcc @3	beq MainLoop1	; If we didn't advance, don't continue;;;	jsl Error	brl MainLoop1@3;             Now update the display	bit DirSelReq	bmi DirDisplay	jsr DispDisk2Update	brl MainLoop1DirDisplay	jsl MakeNewList	jsr DispDir2Update	brl MainLoop1;       Clear the "Switch dialogs flag", close the