ort AlertMsgNo	Import CursorArrowOn	Import DialogPort	Import Dir2Rect	Import Dir2Update	Import DirSelReq	Import DispDir2Update	Import Disk2Rect	Import Disk2Update	Import DrawNewList	Import MyZP	Import OldMsgNo	Import UpdatePopUp** Entry Points:*	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; Save caller's registers and set them for us	phd	; Save caller's direct register	phb	; Save caller's bank register	phk	; Reset bank register...	plb	;  ...to current bank	lda MyZP	; Reset direct register...	tcd	;  ...to Installer's zero page	bit WindowSetupComplete	bmi DrawTheControls	jsr UpdatePopUp	sec	ror WindowSetupComplete; Draw the controlsDrawTheControls	lda DialogPort+2	pha	lda DialogPort	pha	ldx #DrawControls	jsl ToolLocator; Draw the Update stuff.	bit DirSelReq	; Are we displaying	directory or volume?	bmi DispDir	jsr DispDisk2Update	bra DrawAlertDispDir	jsr DispDir2Update; Redraw the alert message, if anyDrawAlert	lda OldMsgNo	sta AlertMsgNo	stz OldMsgNo	jsr AlertMsg	jsr CursorArrowOn	; Re-init cursor just in case this		;  called after "AskForVolume".; Restore caller's registers and return	plb	; Restore caller's bank register	pld	; Restore caller's direct register	rtl	; Return to caller	EndP {CustomProgram}	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * ** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * ** *			* ** *               E V E N T   H A N D L E R S               * ** *			* ** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * ** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * ** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *KeyDown	Proc** Description:	Handles key-presses in Custom Install.  *	Menus and controls handle most keypresses. *	Remaining key presses of interest:*	open-apple-tab —— swaps textEdit boxes as ctlTarget*	open-apple-DownArrow —— same as hitting the OPEN button*	open-apple-UpArrow —— shift target directory up hierarchy to parent**	NOTE: open-apple-"Q" is handled through the menuMgr since*	      QUIT is also a menu item.** Inputs:	none** Outputs:	none** External Refs:	Import AdjustDir	Import CheckHilite	Import CloseDir	Import CursorArrowOn	Import DialogPort	Import DirSelReq	Import inControl	Import MenuItemID	Import OpenCtlHdl	Import OpenSub	Import PopOne	Import Task:TaskRecord	Import UpdatePopUp** Entry Points:*	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	ldy Task.Message	; Get the keypress; Is it the rightArrow key? (throw it away)	cpy #RightArrowKey	; since we're using left arrow, don't let 	beq KeyDownExitj	;  other arrow through to Target control; Check for remaining key presses based on if AppleKey is down.NextKey	lda Task.Modifiers	; Only want to look	at AppleKey	and #appleKey	; Is AppleKey down?	bne GotAppleKey; Apple key is not down	cpy #Tab	bne notTab; is it TAB? (tab swaps list boxes as ctlTarget)	bit DirSelReq	; Appl Folder Selection list 	bpl KeyDownExitj	;   is only active when directory selection is required.	pha	; ok:  swap textEdit boxes as ctlTarget	pha	ldx #MakeNextCtlTarget	jsl ToolLocator	pla	pla	; don’t care which control: there are only 2KeyDownExitj	bra KeyDownExitnotTab; Is it the Escape key? (shifts target directory up hierarchy to its parent directory)	cpy #Escape	beq FoundUpArrow	; same as apple-UpArrow	bra ListKey	; else send key to controls: equivalent?; Apple key is downGotAppleKey; is it apple-DownArrow? (opens the selected folder)	cpy #DownArrowKey	bne notDownArrow	ldx OpenCtlHdl	; Check the control to see if it is active	ldy OpenCtlHdl+2	jsr CheckHilite	beq KeyDownExit	jsr OpenSub	bra DonenotDownArrow; is it apple-UpArrow? (shifts target directory up hierarchy to its parent directory)	cpy #UpArrowKey	bne notUpArrowFoundUpArrow	lda MenuItemID	; can only go up if more than 1 item in popup	cmp #2	bcc KeyDownExit	jsr PopOne	; Remove one name from CurDirectory	jsr AdjustDir	; make new list in App Folder Selection window	bra doPopUpnotUpArrow; is it apple-Esc? (shifts target directory to root directory)	cpy #Escape	bne notAppleEsc	lda MenuItemID	; can only go up if more than 1 item in popup	cmp #2	bcc KeyDownExit	; bra if less than 2	lda #1	; back to root level	jsr CloseDir	; Back prefix up to root & display new dir listdoPopUp	jsr UpdatePopUp	; update the popup itself	bra KeyDownExitnotAppleEsc; done with apple-x commands; Send all remaining keys to the target controlListKey	pha	; space for result	pea 0	; send to all control	lda DialogPort+2	; Window to check	pha	lda DialogPort	pha	pea Task>>16	pea |Task	ldx #SendEventToCtl	jsl ToolLocator	pla	; was key accepted?	bne inControl	; bra if key was a key equivalent of controlDone	jsr CursorArrowOnKeyDownExit	lda #0000	clc	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *CheckHilite	Proc** Description:	Accesses the control's record and check the ctlHilit*	value to see if it is active or not.** Inputs:	X & Y contain handle to the control record** Outputs:	zFlag set: control is inactive (beq Inactive)*	zFlag clear: contorl is active (bne Active)** External Refs:	Import Dereference* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	phy	phx	jsl Dereference	pla	sta <ZPTemp	pla	sta <ZPTemp+2	ldy #octlHilite	lda [<ZPTemp],y	and #$00FF	cmp #$00FF	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *inControl	Proc** Description:	inControl event handler...checks to see if we went down*	in an active control and blinks it if we did.   ** Inputs:	none** Outputs:	none** External Refs:	Import CursorArrowOn	Import CursorWatchOn	Import DialogPort	Import DiskSub	Import EjectSub	Import HandleTable	Import HelpSub	Import InstallSub	Import ScriptListSub	Import FolderListSub	Import NewFolderSub	Import PopUpSub	Import OpenSub	Import RemoveSub	Import QuitSub	Import Standard2Sub	Import Task:TaskRecord** Entry Points:*	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; MouseUp occurred in the same control we went down in.; ControlID is in Task.Data4; ControlHandle is in Task.Data2.; Dispatch the control request.	ldy #0000	; Initial indexCompareLoop	lda HandleTable,y	iny	iny	cmp Task.Data2	bne NextCtlPtr	lda HandleTable,y	cmp Task.Data2+2	beq FoundControlNextCtlPtr	iny	iny	bra CompareLoop; Dispatch the user	control requestFoundControl	dey	; Back the index up	to the beginning of	dey	;   the handle.	tya	; Move to A-reg	lsr a	; Divide by two to form index	pha	; Save on stack...	jsr CursorWatchOn	; ...change to watch cursor...	plx	;    ...pull index into X-reg...	jsr (CtlDispTbl,x)	;       ...and dispatch the request.	jsr CursorArrowOn	; Restore arrow cursorIgnore	rts	; ('Do-nothing' subroutine); . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; The following subroutine dispatch table must be in the same order as the; handle table (HandleTable) found in 'Data.Asm'.CtlDispTbl	dc.w InstallSub	;	      	00	dc.w RemoveSub	;	      	02	dc.w HelpSub	;	      	04	dc.w QuitSub	;	      	06	dc.w DiskSub	;	      	08	dc.w OpenSub	;	      	0A	dc.w EjectSub	;	      	0C	dc.w NewFolderSub	;	      	0E	dc.w Ignore	; Hit in StatText1Ctl     	10	dc.w Ignore	; Hit in StatText2Ctl     	12	dc.w Ignore	; Hit in PictureCtl       	14	dc.w ScriptListSub	; Hit in Script selection window	16	dc.w FolderListSub	; Hit in Directory List selection wdw	18	dc.w PopUpSub	;	      	1A	dc.w Standard2Sub	;                         	1B	dc.w Ignore	; Hit in List1 scroll bar 	1C	dc.w Ignore	; Hit in List2 scroll bar 	1E	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *InMenu	Proc** Description:	inMenu event handler:*	   'About Installer...'*	   'Initialize Disk...'*	   'Quit' *	   'Installer Help'*	   'Creating a New System Disk'*	   'Updating an Existing Disk'*	   'Hard Disk Initialization'*	   'Keyboard Shortcuts'** Inputs:*	none** Outputs:*	none** External Refs:	Import AboutMsg	Import CloseTarget	Import CreatingSub	Import CurrentVol	Import Dev_Name	Import DialogFlag	Import DirSelReq	Import EndAboutMsg	Import Error	Import HardDiskSub	Import HelpSub	Import Help2Sub	Import MakeNewList	Import NextSameDevice	Import OneSimpleKeyFilter	Import OKStr	Import QuitSub	Import ShortcutsSub	Import Task:TaskRecord	Import ThisMode	Import UpdatingSub** Entry Points:*	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	lda Task.Data	; ID of menu item	cmp #EraseDiskItemID ; If it is our 'Erase Disk...'	beq DoEraseDisk	;   put up dialog to erase disk	cmp #ShortcutsItemID ; If it is our 'Keyboard Shortcuts'	beq HelpKbdShortcuts ;   build a dialog	cmp #HelpItemID	; If it is our 'Installer Help...'	beq HelpDialog	;   do the same as is done for Help button	cmp #CreatingItemID	; If it is 'Creating a New System Disk'	beq CreatingDialog	cmp #UpdatingItemID	; If it is 'Updating an Existing Disk'	beq UpdatingDialog	cmp #HardDiskItemID	; If it is 'Hard Disk Initialization'	beq HardDiskDialog	cmp #AboutItemID	; If it is our 'About Installer...'	beq AboutInstaller	;   build a dialog	cmp #QuitItemID	; If it is QUIT, then QUIT	bne Unhilite	;   else, we're not interested	jsr QuitSub	bra UnHilite; Put up Help dialog for Installer, based on which dialog we're inHelpDialog	bit DialogFlag	bmi @StandardDialog	jsr HelpSub	; Custom Update	bra UnHilite@StandardDialog	jsr Help2Sub	; Easy Update (Standard Install)	bra UnHilite; Erase the target diskDoEraseDisk	jsr CloseTarget	; close root directory (no open files allowed during erase)	jsl GSOS	dc.w EraseDisk	dc.l Erase_Parms	bcc CheckForNewName	tax	; check for zero (user pressed Cancel)	beq SkipDisplay	jsl ErrorCheckForNewName	jsr NextSameDevice	; check current device: update name, controls	bcs SkipDisplay	; Oops! No on-line volumes!; Change the List to contain the root directory of the new volume	bit DirSelReq	bpl SkipDisplay	jsl MakeNewListSkipDisplay	bra UnHilite; Put up 'Creating a New System Disk' dialogCreatingDialog	jsr CreatingSub	bra UnHilite; Put up 'Updating an Existing Disk' dialogUpdatingDialog	jsr UpdatingSub	bra UnHilite; Put up 'Hard Disk Initialization' dialogHardDiskDialog	jsr HardDiskSub	bra UnHilite; Put up keyboard shortcuts help dialogHelpKbdShortcuts	jsr ShortcutsSub; NOTE: The special	menu above the directory selection window must be redrawn; as a separate action.UnHilite	pea Active	; unhilite it (normal)	lda Task.Data+2	; ID of menu	pha	ldx #HiliteMenu	jsl ToolLocator	lda #0000	clc	rtsErase_Parms	dc.w 5	; Parameter count	dc.l Dev_Name+2	; Device name pointer	dc.l CurrentVol	; supplied volume name: the current target	dc.w 00	; result (fileSysID)	dc.w proDOSfsID	; default file system: ProDOSErase_Flags	dc.w fFormatEdit+fFormatSelect ; flags: editable name, selectable file sys	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; User has asked for information about the Installer Program.AboutInstaller	pha	; Room for result	pha	pea AboutTemplate>>16	pea |AboutTemplate	ldx #GetNewModalDialog	jsl ToolLocator	; (Leave pointer on stack for CloseDialog)	pha	; Room for result	pea OneSimpleKeyFilter>>16 ; filterProcPtr	pea |OneSimpleKeyFilter	ldx #ModalDialog	jsl ToolLocator	pla	; Only one response possible	ldx #CloseDialog	; Close the dialog	jsl ToolLocator	;  (pointer still on stack)	bra UnHilite;................................................................AboutTemplateAboutRect	dc.w 60,160,150,480	; Bounds rect	dc.w $FFFF	; Visible	dc.l 00000000	; Ref con	dc.l Item1	dc.l Item2	dc.l 00000000Item1	dc.w 1	; ID	dc.w 74,210,86,285	; Bounds rect 