ontrolSubExit	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .DiskSub;; DiskSub will advance to the next connected device and retrieve; the volume name, place the volume name at '<CurDirPtr' and redraw; the PopUp control.  A new list for the List Window will be created; if directory selection is required, and _NewList will be called.; (After 14 attempts to get another volume, NextDevice1 will give up; and issue an error.); . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Now get the next volume name and move	it into <CurDirPtr.DiskSub1	jsr NextDevice1	; Advance always	bcs DiskExit	; Oops! No on-line volumes!; If we previously had no volumes on line, we need to get deactivated; buttons set up again by checking the script's needs.	bit NoVolumes	bpl @1	stz NoVolumes	jsr CheckScript@1; Change the List to contain the root directory of the new volume	bit DirSelReq	bpl @SkipDisplay	jsl MakeNewList@SkipDisplay; Dim or activate the Eject Button based on the characteristics of the drive	clc	; Indicate everything went OK	lda #0000; Make the control normal (unhilited) again.DiskExit	pha	; Preserve the A-reg	jsl FlushEventQueue	pla	; Restore error code, if any	brl ControlSubExit	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .OpenSub;; OpenSub opens the currently selected folder.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Check to see which item in the list is selected.@1	pha	; Room for result	pea 0000	; Start at beginning of list	lda SelectListCtlHdl+2 ; Control's handle	pha	lda SelectListCtlHdl	pha	ldx #NextMember2	jsl ToolLocator	pla	sta CurrentMember ; Member that just got hit; If returned value	was null, nothing was selected.	beq OpenFinished; If we "got something", we need to get the pointer to the string into; "CurrentMember".GotSomething;       Dereference the List's handle	lda AppFolderListHdl+2	pha	lda AppFolderList