orChar	beq @Oops@00	dey	bne @0	bra @BuildName; There was a separator character in the folder name@Oops	rep #$0030	LongA On	LongI On	lda #$008F	jsl Error	bra InputLoop1	; Try again; Build a full path name for the user requested folder name.; (<CurDirPtr + FolderPath)@BuildName	rep #$0030	LongA On	LongI On;       Lock and dereference <CurDirHdl, placing the pointer in <CurDirPtr,;       and convert FolderPath to a GStr in FolderPathBuf	jsl GetCurDirPtr	ldy #0002	; (Get the length word in case we	lda [<CurDirPtr],y	;  get an error and have to go	sta OldLength	;  back to the original name.)	pea FolderPath>>16	pea |FolderPath	pea GStrBuffer>>16	pea |GStrBuffer	jsl PStrToGStr;       Check for trailing separator character and if there is none, add one.	ldy #0002	; Get the lengthWord	lda [<CurDirPtr],y	clc	adc #GStrOverhead-1	; Add on GStr buffer overhead	tay	;  and use as index to last character	lda [<CurDirPtr],y	and #$00FF	cmp #SeparatorChar	beq @Concat;       Gotta add a trailing separator before we can concatenate.	pea SeperatorBuf>>16 ; First GStr buffer pointer	pea |SeperatorBuf	pei <CurDirPtr+2	; Destination GStr buffer pointer	pei <CurDirPtr	jsl Concat;       Concatenate "FolderPath" onto the pathname at "<CurDirPtr"@ConCat	pea GStrBuffer>>16	pea |GStrBuffer	pei <CurDirPtr+2	; Destination GStr buffer pointer	pei <CurDirPtr	jsl Concat; Attemp to create the new folder	pha	; Space for result	pha	pei <CurDirPtr+2	; GStr buffer pointer	pei <CurDirPtr	jsl GStrAsC1Inp	pla	; C1Inp buffer pointer	sta CreatePath	pla	sta CreatePath+2@1	jsl GSOS	dc.w Create	dc.l CreateParms	bcc NewFolderOpen	; All OK; Oops!  We got an error!  Notify the user	cmp #DupPathname	; Remap "Duplicate Filename" to...	bne @2	lda #$008E	;  ..."Duplicate Folder Name."@2	cmp #PathSyntax	; Remap syntax error w/ source:<name>...	bne @2a	lda #$008F	;  ... syntax error w/o source:<name>; Gotta special case an incorrect error that can be returned by GS/OS if; the user ask for a NewFolder name starting with a period.@2a	cmp #$0010	; Remap "Device Not Found" to...	bne @3	lda #$008F	;  ... syntax error w/o source:<name>; Gotta special case an incorrect error that can be returned by GS/OS if; the user ask for a NewFolder name containing a colon.@3	cmp #PathNotFound	; Remap "Path Not Found" to...	bne @4	lda #$008F	;  ... syntax error w/o source:<name>@4	ldx CreateParms	ldy CreateParms+2	jsl Error	php	pha; What ever the pathname was, it generated an error!  Take off the last level; of the pathname by restoring the old length word and resizing the buffer.	ldy #0002	lda OldLength	sta [<CurDirPtr],y	jsl ResizeCurDirBuf; When we get an error handler dialog, we need to force the window to re-draw	jsl UpdateMainDialog	pla	plp	bcc @1; Now, process any error conditions returned by the CreateFolder routine	cmp #VolumeNotFound	beq NewFolderExit	brl InputLoop1	; Oops, didn't create the folder; We got the new folder.  Now copy the current directory to the application; directory.NewFolderOpen	pei <CurDirPtr+2	pei <CurDirPtr	pei <AppDirPtr+2	pei <AppDirPtr	jsl GStrToGStr	jsl ResizeAppDirBuf	bcs NewFolderOpen; Perform additional housekeeping chores as needed.	jsr SetPrefix	jsl MakeNewList	jsr DrawNewList	jsr DispDir2Update	jsr UpdatePopUpNewFolderExit	pha	; Preserve error code	lda NewFolderPort+2	pha	lda NewFolderPort	pha	ldx #CloseDialog	; Close the dialog	jsl ToolLocator	jsl FlushEventQueue	pla	; Restore error code, if any	brl ControlSubExitOldLength	ds.w 1; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .CreateParms	dc.w 0006CreatePath	ds.l 1	; Pathname	dc.w Access	; Access	dc.w FileType	; File Type	dc.l AuxType	; Aux Type	dc.w StorageType	; Storage Type	dc.l Creation	; Creation Date and	TimeSeperatorBuf	dc.w 0005	dc.w 0001	dc.b SeparatorChar	Eject	Eject; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .;NewFolderPort	ds.b 4;; template for New Folder dialogdWidth    equ 331dHeight   equ 64dTop      equ (200/2)-(dHeight/2)+22dLeft     equ (640/2)-(dWidth/2)dBottom   equ dTop+dHeightdRight    equ dLeft+dWidthDiaTemplate	dc.w dTop,dLeft,dBottom,dRight ; Bounds rect	dc.w $FFFF	; Visible	dc.l 00000000	; Ref con	dc.l Item1	dc.l Item2	dc.l Item3	dc.l Item4	dc.l 00000000	; End of Item list markerItem1	dc.w 1	; ID	dc.w dHeight-19,dWidth-83 ; itemRect	dc.w dHeight-8,dWidth-18	dc.w ButtonItem	; Type	dc.l OKStr	; Item descriptor	dc.w 0000	; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item colorItem2	dc.w 2	; ID	dc.w dHeight-19,dWidth-169 ; itemRect	dc.w dHeight-8,dWidth-104	dc.w ButtonItem	; Type	dc.l CancelStr	; Item descriptor	dc.w 0000	; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item colorItem3	dc.w 3	; ID	dc.w 7,16,18,186	; Item bounding rect	dc.w StatText+ItemDisable ; Type	dc.l NewFolderMsg	; Item descriptor	dc.w 0000	; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item colorItem4		; EditLineID	equ 4	dc.w EditLineID	; ID	dc.w 23,18,36,dWidth-18 ; Item bounding rect	dc.w EditLine+ItemDisable ; Type	dc.l DefaultString	; Item descriptor	dc.w 0031	; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item colorDefaultString	dc.b DefaultStrEnd-DefaultString-1,'untitled'DefaultStrEndFolderPath	ds.b 33	; Room for LengthByte + 32 bytes	Eject; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .EjectSub;; EjectSub will eject a disk from any drive that can accept eject requests.; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .Begin	lda D_DeviceNum	; Get the device number	sta D_Cont_DevNum	;  and put in parameters	jsl GSOS	dc.w D_Control	dc.l D_Cont_Parms	brl DiskSub1	; Move on to the next device just as if		;  someone pressed the DISK button	Eject; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .ScriptListSub	Name;; ScriptListSub is called when the mouse is clicked in the Script; selection window.	 We must go thru the list of selected scripts; and determine; • if none are selected: turn off help, install, remove buttons; • if any of them require directory selection.  If;   so, we need to activate the directory selection window.; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .	stz DifferentTypes	; Initialize flag	stz NumOfSelections	stz <ZPTemp	; (NOTE: <ZPTemp = zero)	stz <ZPTemp+2	stz MemberNum	jsr GetNextFlag	; Get first members flag	sta SelectedScriptFlags	bcc @SomeMemberSelected; There is NO member selected at all!!!  Deactivate Install, Remove, and Help.	lda #AlertMsg1	sta AlertMsgNo	lda InstallRemoveMode ; Dim the Install & Remove Controls	ora #bNoScripts	; no scripts selected	stz DirSelReq	; keep Application Folder Selection list clear	sta InstallRemoveMode	brl SetControls2; There is at least one member selected.@SomeMemberSelected	lda InstallRemoveMode ; Dim the Install & Remove Controls	and #≈bNoScripts	; force bit to 0	sta InstallRemoveMode	lda <ZPTemp	sta CurrentMember	lda <ZPTemp+2	sta CurrentMember+2	lda SelectedScriptFlags	bra MidLoop;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; Now start looking for more selectionsSearchLoop	jsr GetNextFlag	; Get next member flag	bcs NoMoreSelectedMidLoop	tax	; Save current flag	inc NumOfSelections	; Increment the number of selections; Check if the selections are of the same "type".; If the hi-bit of the two ScriptFlags does not match:;   both 'select-application' and 'system' scripts have been selected;;   set hi bit of DifferentTypes as flag ;     to let the "talking head" explain the rules of the game before we exit.	eor SelectedScriptFlags ; Do hi-bits match	bpl @doneTypeCheck	sta DifferentTypes	; store 1 in hi bit if they don't match@doneTypeCheck;       We must save in SelectedScriptFlags, if ANY selected script has it set:  ;            bit 15: directory selection needed;            bit 14: disable REMOVE as a valid command;            bit 13: prevent installation to Boot disk	txa	; check current flag	and #bDirReq|bPreventBoot|bNoRemove  ; bits to OR into SelectedScriptFlags	ora SelectedScriptFlags	sta SelectedScriptFlags;       We must save in SelectedScriptFlags, only if ALL selected scripts have it set:;            bit 14: disable REMOVE as a valid command; REMOVE THIS CODE IF WORKS WITHOUT IT!!!!!!!!!!!!!!!!!!!!!!!!!!!;	txa	; check current flag;	ora #≈bNoRemove	; EOR bit (now %11011...): get bit to AND into SelectedScriptFlags;	and SelectedScriptFlags;	sta SelectedScriptFlags	bra SearchLoop;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; DO ACTIONS;;;;;;;;;;;;;;;;;;;;;;;;;;; We've found all the selected membersNoMoreSelected; INSTALL & REMOVE BUTTONS....................................................; if PreventBoot flag set & VolStr (boot volume) = CurrentVol (current volume);     turn off Install & Remove buttons 	lda SelectedScriptFlags	and #bPreventBoot	; Is PreventBoot valid?	beq @BootOK;       PreventBoot is valid: if VolStr = CurrentVol, turn Install button off	ora InstallRemoveMode ; set Prevent bit	bra @DonePrevent@BootOK	lda #bPreventBoot--$FFFF ; clear Prevent bit	and InstallRemoveMode ; clear Prevent bit@DonePrevent	sta InstallRemoveMode; Activate or deactivate the REMOVE button as is appropriate based on Remove flag.	lda SelectedScriptFlags	and #bNoRemove	; Is RemovePrevent flag set?	beq @ActivateRemove	ora InstallRemoveMode ; set Remove bit	bra @DoneRemove@ActivateRemove	lda #bNoRemove--$FFFF ; clear Remove bit	and InstallRemoveMode ; clear Remove bit@DoneRemove	sta InstallRemoveMode; TALKING HEAD......................................................; are there both 'select-application' and 'system' scripts selected?	bit DifferentTypes	; If all are the same type...	bpl @NoMsgNeeded	;  ...we can continue;       Both types of scripts are in the list.  Let the "talking head" explain...	lda #AlertMsg3	; Alert user: some require directory selection, some not	bra @DisplayMsg;       Only one type of script in list.  No message needed.@NoMsgNeeded	lda #AlertNoMsg@DisplayMsg	sta AlertMsgNo; HELP ............................................................; Script HELP can only be provided when one and only one script is selected.	lda NumOfSelections	; Was there only one selected?	cmp #0001	bne @AppFolder;       There is only one script selected.  The HelpSub routine;       needs the filename in CurScriptFile	ldx #0000	; Identify the member's position in	clc	;   the list	lda <ScriptListPtr@SearchLoop1	cmp CurrentMember	; (we can ignore hi-word)	beq @GotIt	inx	adc #0006	; (each record is 6 bytes long)	bra @SearchLoop1;       X-reg now contains the member's position in the list.  Its;       filename will be in the same position in the ScriptFileName;       list.  (The records in the ScriptFileName list are exactly;       16 bytes long.)@GotIt	stx Temp	; Multiply member's position X 6	txa	asl a	clc	adc Temp	asl a	tay	lda [<ScriptFilePtr],y	sta CurScriptFile	iny	iny	lda [<ScriptFilePtr],y	sta CurScriptFile+2; APPLICATION FOLDER SELECTION LIST................................................; Get the <CurDirPtr set and fix CurDirectory so that it holds the proper pathname.@AppFolder	jsl GetCurDirPtr	bit DirSelReq	php	; save previous setting: needed folder selection?	lda SelectedScriptFlags ; save off bit 15 (ignore rest): need folder selection?	sta DirSelReq	bpl SetControls;       Directory selection is required. Move Application Directory into buffer;       at <CurDirPtr.	jsl GetAppDirPtr@TryAgain	pei <AppDirPtr+2	pei <AppDirPtr	pei <CurDirPtr+2	pei <CurDirPtr	jsl GStrToGStr	jsl ResizeCurDirBuf	bcs @TryAgain;       Do NOT recreate the list if directory selection was previously required (it's ok).	plp	; saved previous setting: needed folder selection?	php	bmi @SkipMakeNewList ; branch if previous DirSelReq flag was set	jsl MakeNewList@SkipMakeNewList	jsr BuildDirName	; build short vs. of name for display purposes	jsl UnlockCurDirHdl	; Let it float til needed again	; Many of the controls depend on the script's requirementsSetControls	plpSetControls2; set Install and Remove buttons based on InstallRemoveMode flags	jsr SetInstallRemove 	bit WindowSetupComplete ; Don't draw it til set up complete	bpl @SkipAlertMsg	jsr AlertMsg@SkipAlertMsg	jsr CheckScript;;;	jsr CursorArrowOn	lda #0000	brl ControlSubExit; bit 15 set = Directory Selection needed; bit 14 set = REMOVE is validSelectedScriptFlags	ds.w 1	DifferentTypes	ds.w 1	; bit 15 set = different types of scripts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .GetNextFlag;; Description:	GetNextFlag is a local subroutine for ScriptListSub.;	It puts the pointer to the next member in <ZPTemp, the;	pointer to the next member's string in <ZPTemp1, and;	returns the member's ScriptFlag value in the A-reg.;; Inputs:	MemberNum contains the memNumber to start searching from.;; Outputs:	if carry is clear:;	    A-reg = Member's ScriptFlag value;	    <ZPTemp1 = Pointer to next member;	    <ZPTemp = Pointer to next member's string;	    status flags = value from loading ScriptFlag value;	if carry is set: no more members selected;	    <ZPTemp = 0; External Ref:	Import MemberNum	Import ScriptListCtlHdl; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Begin the search from the member who's identified in "MemberNum"	pha	; Room for result	lda MemberNum	; MemNumber to start search from	pha	lda ScriptListCtlHdl+2 ; Handle to control	pha	lda ScriptListCtlHdl	pha	ldx #NextMember2	jsl ToolLocator	pla	sta MemberNum; If the returned member number is zero, there were no more members selected.	bne SetUpPointer	stz <ZPTemp	stz <ZPTemp+2	sec	bra GetNextDone; There are more marked.  Set up <ZPTemp to point to the member and <ZPTemp1 to; point to the member's ScriptName string.SetUpPointer	dec a	; Index beginning at zero, not one	sta Temp	asl a	; Multiply by six to calculate offset	clc	adc Temp	asl a	clc	adc <ScriptListPtr	sta <ZPTemp	lda #0000	adc <ScriptListPtr+2	sta <ZPTemp+2	lda [<ZPTemp]	; Get the pointer to the member string	sta <ZPTemp1	ldy #0002	lda [<ZPTemp],y	sta <ZPTemp1+2; Get the ScriptFlags word from the end of the member's ScriptName string	lda [<ZPTemp1]	; Get the lengthbyte + 1st character	and #$00FF	; Mask off the 1st character	inc A	; Point position following string	tay	; Use as index...	lda [<ZPTemp1],y	;  ...to access ScriptFlags word	clcGetNextDone	rts; Miscellaneous Local data		; bit 15 set = directory selection requiredTemp	ds.w 1	Eject; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .FolderListSub;; FolderListSub is	called when the mouse is clicked in the; Directory List scrolling window.  So,	checks to see if the hit; was on the same list member as the last hit and then checks to; see if the elapsed time since the last hit is within the limits; set in the Control Panel.  If it is not a legitimate "double; click", the list member that was hit and the tick count are; recorded for comparison the next time.;	Import NoMemberSelected; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .; First check to see if we hit the same	item a second time.	pha	; Room for result	pea 0000	; Start at beginning of list	lda SelectListCtlHdl+2 ; Control's handle	pha	lda SelectListCtlHdl	pha	ldx #NextMember2	jsl ToolLocator	pla;       If the member item number is null, nothing was hit.	bne @1	brl Finished;       Get the member's pointer@1	jsr GetMemPointer	stx <ZPTemp	stx CurrentMember	sta <ZPTemp+2	sta CurrentMember+2;       Did we hit a disabled member?  If we did, nothing will be hilited, so;       be sure to disable the Open control.	ldy #0004	; Pick up the MemFlag byte	lda [<ZPTemp],y	and #%0000000011000000 ; Is it an 'invalid value'	cmp #%0000000011000000	bne Enabled	sec	ror NoMemberSelected ; (and set flag <>0)	lda #Inactive	; Yeah!  Disable the OPEN button	jsr OpenControl	brl Finished	;  ...and we're done; It is enabled.  Was it made with the mouse or the keyboard?Enabled	lda Task.what	cmp #mouseDownEvt	beq MouseClick 	stz OldMember	; key selection: don’t allow following mouse	stz OldMember+2	;   click to be considered a double-click	bra ItsActive; Made by mouse.  Was it a double click?MouseClick	lda <ZPTemp	ldx <ZPTemp+2	cmp OldMember	; Is it the same as	OldMember?	bne NotTheSame	cpx OldMember+2	beq TheSame; They're not the same, so move CurrentMember to OldMember, record tick; and be sure the OPEN button is active.NotTheSame	sta OldMember	stx OldMember+2	lda Task.When	sta OldTick	lda Task.When+2	sta OldTick+2ItsActive	stz NoMemberSelected ; set flag for CheckScript	lda #Active	jsr OpenControl	brl Finished; They're the same.  Now get the difference between Task.When and the OldTick.; Then compare it with the Control Panel setting.TheSame	sec	lda Task.When	sbc OldTick	sta TickDiff	lda Task.When+2	sbc OldTick+2	sta TickDiff+2	pha	; Room for result	pha	ldx #GetDblTime	jsl ToolLocator	pla	sta DoubleTime	; Get maximum double-click time	plx	stx DoubleTime+2	cmp TickDiff	;  ...compare the difference	lda DoubleTime+2	sbc TickDiff+2	bcs @1	; It is a legitimate double click@setupNotSame	lda CurrentMember	; Too long to be legitimate double click	ldx CurrentMember+2	bra NotTheSame@1; It IS a legitimate double click!  Concatenate the name of	CurrentMember to the; CurrentDir name and build and display	the new list.	jsr AddToDir;Finished	lda #0000	brl ControlSubExit; A few local variables used by ScriptListSub and FolderListSubOldMember	ds.b 4OldTick	ds.b 4TickDiff	ds.b 4DoubleTime	ds.b 4	Eject; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .AddToDir	Name;; AddToDir is a local subroutine.  First it will check the access; privileges of the folder.  If we have both read and write; privileges, it will concatenate CurrentMember to the GStr at; <CurDirPtr, adjust the names in the special menu above the; directory selection window, and build and display the new list.; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .	lda #0002	; Get_File_Info pCount	sta GetInfo.pCount	;  (only need pathname & access);       The List Mgr list is made up of Pascal Strings.  We must move the PStr;       into our little filename buffer as a class 1 input string.	lda CurrentMember+2	; PStr buffer handle	pha	lda CurrentMember	pha	jsl Dereference	pea FileNameBuffer>>16 ; C1Inp buffer pointer	pea |FileNameBuffer	jsl PStrToC1Inp	lda #FileNameBuffer	sta GetInfo.pathname	lda #^FileNameBuffer	sta GetInfo.pathname+2	jsr SetPrefix	jsl GSOS	dc.w Get_File_Info	dc.l GetInfo	bcc CheckAccess	ldx GetInfo+2	ldy GetInfo+4	jsl ErrorExit1	brl Exit;       Check access privilegesCheckAccess	lda GetInfo.Access	and #%0000000000000011	cmp #%0000000000000011 ; Read and write enabled?	beq writeable; Oops!  Not writeable!	lda #AlertMsg2	   	bra StoreAlertMsg; writeablewriteable	lda #AlertNoMsgStoreAlertMsg	sta AlertMsgNo	jsr AlertMsg; Concatenate CurrentMember to the CurDirectory name.Concatenate	jsl GetCurDirPtr	; Lock and dereference <CurDirHdl	lda CurrentMember+2	; PStr buffer handle	pha	lda CurrentMember	pha	jsl Dereference	pea GStrBuffer>>16	; GStr buffer pointer	pea |GStrBuffer	jsl PStrToGStr		pea GStrBuffer>>16	; String to concatenate	pea |GStrBuffer	pei <CurDirPtr+2	; String to concatenate onto	pei <CurDirPtr	jsl Concat;       Now give us a copy in Application Directory	jsl GetAppDirPtr@TryAgain	pei <CurDirPtr+2	; GStr source buffer	pei <CurDirPtr	pei <AppDirPtr+2	; GStr destination buffer	pei <AppDirPtr	jsl GStrToGStr	jsl ResizeAppDirBuf	bcs @TryAgain	jsl UnlockAppDirHdl	jsr BuildDirName	jsr DispDir2Update	jsl UnlockCurDirHdl	; Let it float til needed again; Update the pop-up menu and display the new list.	jsr UpdatePopUp	jsl MakeNewList	; (always)	bcs Exit	jsr SetPrefixExit	rtsDirLevel	ds.b 2FileNameBuffer	ds.b 34	Eject; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .PopUpSub;; PopUpSub is called when the hit occured in the special PopUp; menu above the Directory List Window.;; The volume name is menu item #1.  Each successive level in the hierarchy is; the next successive menu item ID.  MenuItemID contains the ID of the last; menu item created.  To remove items, we merely start with the item ID returned; by GetCtlValue and keep incrementing in a loop until we get up to the value; contained in MenuItemID.; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .; First be sure that the menu is supposed to be active	bit DirSelReq	; Is directory selection required?	bpl PopUpDone	pha	; The control value tells us which menu	lda MyPopUpCtlHdl+2	;   item the user hit.	pha	lda MyPopUpCtlHdl	pha	ldx #GetCtlValue	jsl ToolLocator	pla	; If user selected last item created,	cmp MenuItemID	;   there's nothing to do.	beq PopUpDone	jsr CloseDir	; Back up to the selected level		;  and display new list	jsr UpdatePopUpPopUpDone	lda #0000	brl ControlSubExit	Eject;. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .CloseDir;;  CloseDir is a subroutine to back-up (n) levels in the;  directory structure as directed by the user when he makes a;  selection in the	special menu above the directory selection;  window.;;   Inputs:  A-reg contains the ID of the menu item selected.;;. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .CloseDirLoop	pha	; Back up, one at a time	jsr PopOne	; Remove one name from CurDirectory	pla	inc a	cmp MenuItemID	bne CloseDirLoopAdjustDir	jsl MakeNewList	; (always)	jsr DispDir2Update	bcs CloseDirExit	jsr SetPrefixCloseDirExit	rts	Eject;. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .PopOne;	; Search backwards for the preceeding SeparatorChar in CurDirectory; and reset the length word to this new length;. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	jsl GetCurDirPtr	jsl GetAppDirPtr	lda [<CurDirPtr]	; Get buffer size and adjust to form	dec a	;   index to last "real" character	dec a	;   (ignore trailing null & separator character)	tayNotYet	dey	dex	lda [<CurDirPtr],y	and #$00FF 	cmp #SeparatorChar	bne NotYet		; Found the separator	tya	; Convert index back to LengthWord	dec a	dec a	dec a	ldy #0002	sta [<CurDirPtr],y	sta [<AppDirPtr],y	jsl ResizeCurDirBuf	jsl ResizeAppDirBuf	sep #$0020	LongA Off	LongA On	rep #$0020	jsl UnlockCurDirHdl	; Let it float til needed again.	rts	Eject; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .Standard2Sub;; Sets bit zero of the QuitFlag;; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .	lda QuitFlag	ora #%0000000000000001	sta QuitFlag		lda #0000	; Fall thru to ControlSubExit, below; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .ControlSubExit;; This is the all purpose exit routine.  ; Error Code is in accumulator.;; . . . . . . . . .	. . . . . . . . . .	. . . . . . . . . .	. . .	cmp #$0001	; Condition cFlag	rts	EndP	End